import java.util.*;
public class Solution{public static void main(String[]a){Scanner sc=new Scanner(System.in);int n=sc.nextInt();int[]arr=new int[n];for(int i=0;i<n;i++)arr[i]=sc.nextInt();Deque<Integer>stk=new ArrayDeque<>();for(int x:arr){boolean alive=true;while(alive&&x<0&&!stk.isEmpty()&&stk.peek()>0){if(stk.peek()<-x)stk.pop();else if(stk.peek()==-x){stk.pop();alive=false;}else alive=false;}if(alive)stk.push(x);}int[]res=new int[stk.size()];for(int i=res.length-1;i>=0;i--)res[i]=stk.pop();StringJoiner sj=new StringJoiner(" ");for(int v:res)sj.add(String.valueOf(v));System.out.println(sj);}}
